entries[116767] = { ["name"] = "Saphirblaue Flussbestie", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure saphirblaue Flussbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Farbe des Tiers ähnelt dem klaren Blau der Flüsse Draenors und macht es für Raubtiere im Wasser nahezu unsichtbar.\"\nBeute von:\nSchlickhaut\nZone:\nTalador" }
entries[116768] = { ["name"] = "Mooshautflussfläzer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Mooshautflussfläzer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Mooshaut verteidigt ihr Gebiet aggressiv und versteckt sich häufig im Buschwerk an Flüssen, um ahnungslose Passanten zu attackieren.\"\nVerkäufer:\nDämmerungssucher Krek / Dämmerungssucher Alkset\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n50. + 5.000" }
entries[116769] = { ["name"] = "Schlammrückenflussbestie", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure Schlammrückenflussbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein spezielles Gewebe an den Fußsohlen des Schlammrückens gewährt ihm zusätzlichen Halt in Schlamm und auf rutschigen Untergründen.\"\nGarnisonsmission:\nIst es ein Schiff? Ist es ein Flugzeug? Nein, nur eine Flussbestie!" }
entries[116771] = { ["name"] = "Sonnenfalke der Spitzen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Sonnenfalken der Spitzen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn man in die Augen dieses mystischen Wesens blickt, hat man das Gefühl, man würde in das Herz der Sonne starren. Beim Reiten ist das Tragen einer Schutzbrille anzuraten.\"\nBeute von:\nRukhmar" }
entries[116772] = { ["name"] = "Schattenmähnenstürmer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Schattenmähnenstürmer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ausgestoßene Arakkoa\n- Ehrfürchtig\nVerkaufspreis:\n\"Draeneidichter bezeichnen die Farbe dieses Talbuks als Schatten des Mondlichts im aschgrauen Wald.\"\nVerkäufer:\nRabensprecher Skeega / Schattenweiser Brakoss\nFraktion:\nAusgestoßene Arakkoa - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5. + 5.000" }
entries[116773] = { ["name"] = "Flinker Brisenschreiter", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren flinken Brisenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Draenei haben dieses Reittier, das schnellste aller Talbuks, mit der Aufgabe betraut, ihre Boten und Nachrichten sicher an ihre Ziele zu bringen.\"\nBeute von:\nPfadläufer\nZone:\nSchattenmondtal" }
entries[116774] = { ["name"] = "Zugerittenes Silberfell", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer zugerittenes Silberfell oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Talbuk ist aufgrund seiner Intelligenz beliebt und wird darauf trainiert, im Kampf zu treten und Gegner aufzuspießen.\"\nOrt:\nStall der Garnison" }
entries[116775] = { ["name"] = "Brisenschreiterhengst", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Brisenschreiterhengst oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Vol'jins Speer\n- Ehrfürchtig\nVerkaufspreis:\n\"Die rote Färbung des Brisenschreiters spiegelt sein Temperament wider: lebhaft, stürmisch und tapfer.\"\nVerkäufer:\nDazzerian\nFraktion:\nVol'jins Speer - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5. + 5.000" }
entries[116776] = { ["name"] = "Heller Dornzehrer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren hellen Dornzehrer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Wrynns Vorhut\n- Ehrfürchtig\nVerkaufspreis:\n\"Dieser Talbuk ernährt sich ausschließlich von Disteln und Dornen, weshalb sein Inneres genauso widerstandsfähig ist, wie sein Äußeres.\"\nVerkäufer:\nMagor Geistbeuger\nFraktion:\nWrynns Vorhut - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5. + 5.000" }
entries[116777] = { ["name"] = "Boshafter Kriegswidder", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegswidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Bevor er Eure empfindlichsten Körperregionen nicht mit seinem Kopf rammt, hat er Euch nicht wirklich als seinen Reiter akzeptiert.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[116778] = { ["name"] = "Boshafter Kriegsraptor", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Weil scharfe Zähne und Klauen einfach nicht ausreichen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[116779] = { ["name"] = "Stahlzahngarn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Stahlzahngarn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Trainer versuchte einst, das Maul des Stahlrachenwolfs mit Metalldekorationen zu verschönern. Drei Tage hat es gedauert, bis er sein Material zurückhatte.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[116780] = { ["name"] = "Terrorzahn des Kriegshymnenklans", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Terrorzahn des Kriegshymnenklans oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Tier hat einen eisernen Willen, doch wenn Ihr ihm einen Grollhufknochen zum Zerkauen bringt, ist es ganz lieb.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[116781] = { ["name"] = "Gepanzerter Frostwolf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren gepanzerten Frostwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er ist dazu ausgebildet, das harsche Wetter des Frostfeuergrats zu überleben, also kuschelt er, als würde sein Leben davon abhängen.\"\nErfolg:\nStallmeister" }
entries[116782] = { ["name"] = "Eisenflankenkriegswolf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Eisenflankenkriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Orcs des Lachenden Schädels\n- Ehrfürchtig\nVerkaufspreis:\n\"An seinem Schwanz hängt ein gepanzerter Stachel. Wenn Ihr seinen Bauch unbedingt kraulen wollt, tut Ihr es auf eigene Gefahr.\"\nVerkäufer:\nHau'tot\nFraktion:\nLachender Schädel - Ehrfürchtig\nOrt:\nGarnison - Handelsposten (Horde)\nKosten:\n5. + 5.000" }
entries[116784] = { ["name"] = "Zugerittener Knurrer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zugerittenen Knurrer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Welpe unheimlich süß. Jetzt nicht mehr so sehr.\"\nQuest:\nStall der Garnison" }
entries[116785] = { ["name"] = "Schneller Frostwolf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren schnellen Frostwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Frostwolforcs\n- Ehrfürchtig\nVerkaufspreis:\n\"In den kalten Höhen des Frostfeuergrats jagen die Frostwölfe allem nach, was sie fangen können. Die Schnellsten von ihnen bekommen reichlich zu beißen.\"\nVerkäufer:\nBeska Rothauer\nFraktion:\nFrostwolforcs - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5. + 5.000" }
entries[116786] = { ["name"] = "Rauchgrauer Terrorwolf", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren rauchgrauen Terrorwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Man vermutet, dass sie größtenteils im Norden hausen. Können Hochzeiten absolut nicht leiden.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[116788] = { ["name"] = "Todesrad des Kriegsherrn", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Todesrad des Kriegsherrn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses brüllende Ungetüm wird häufig als \"Goblinrasenmäher\" bezeichnet, da dieses knurrende Monstrum Feinde behandelt, als wären sie aus Gras... das bereit ist, gemäht zu werden.\"\nErfolg:\nKategorie:\nHeldentaten" }
entries[116789] = { ["name"] = "Kettenrad des Champions", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Kettenrad des Champions oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Menschen, Gnome und Zwerge haben gemeinsam dieses gepanzerte Meisterstück geschaffen, das einen Tauren im Handumdrehen in mundgerechte Stücke zerteilt.\"\nVerkäufer:\nPaulie\nZone:\nSturmwind, Altstadt\nKosten:" }
entries[116791] = { ["name"] = "Kriegsyeti des Herausforderers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Kriegsyeti des Herausforderers oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Glücklicherweise bewegen sie sich schnell und hinterlassen nur den Geruch.\"\nErfolg:\nHerausforderungskriegsherr: Silber" }
entries[116792] = { ["name"] = "Sonnenhautgronnling", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Sonnenhautgronnling oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Liebt die Sonne und hasst alles andere.\"\nBeute von:\nRammfaust\nZone:\nGorgrond" }
entries[116794] = { ["name"] = "Nachtheuler der Garn", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Nachtheuler der Garn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Garn gehören zu den gefährlichsten Raubtieren in Draenor und jagen immer im Rudel.\"\nBeute von:\nNok-Karosh\nOrt:\nFrostfeuergrat" }
