entries[116797] = { ["name"] = "Pokhars achte Axt", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n4 - 9 Schaden Geschwindigkeit 2.60\n(2.5 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90\n\"Acht Äxte zu tragen, mag manchen ja übertrieben erscheinen. Pokhar sieht es anscheinend aber nicht so.\"\nVerkaufspreis:" }
