entries[116817] = { ["name"] = "Oschi des Schwarzwassers", ["text"] = "Wird beim Aufheben gebunden\n\"Lähmt seine Beute mit einem kräftigen Schwanzhieb. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116818] = { ["name"] = "Oschi der Tiefsee", ["text"] = "Wird beim Aufheben gebunden\n\"Dank seines lächerlich überdimensionierten Kopfes und Mauls kann er Beute verschlingen, die größer ist als er selbst. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116819] = { ["name"] = "Oschi der Feuerammoniten", ["text"] = "Wird beim Aufheben gebunden\n\"Ein magischer 'Fisch', der in Lava lebt und der wie ein Tintenfisch in einer kegelförmigen Muschel aussieht. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116820] = { ["name"] = "Blinder Seeoschi", ["text"] = "Wird beim Aufheben gebunden\n\"Hat keine Augen, daher 'sieht' er mit seinen Barteln. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116821] = { ["name"] = "Dicker Schläferoschi", ["text"] = "Wird beim Aufheben gebunden\n\"Hässlich und schleimig. Gekocht erstaunlich lecker. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116822] = { ["name"] = "Kieferloser Laueroschi", ["text"] = "Wird beim Aufheben gebunden\n\"Ein seltsamer Fisch ohne Maul und mit einer ungespaltenen Schwanzflosse. Ernährt sich von pflanzlichen Lebensenergien. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[116823] = { ["name"] = "Katealystischer Konverter", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Eure Heilzauber verfügen über eine Chance, 10 Sek. lang 17 Intelligenz zu verleihen. (Procchance: 10%, 30s Abklingzeit)\n\"Zum Patent angemeldet\"\nVerkaufspreis:" }
entries[116824] = { ["name"] = "Horn eines tollwütigen Talbuks", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Tempowertung um + 6.\nAnlegen: Eure Angriffe haben eine Chance, Euch 20 Sek. lang 17 Beweglichkeit zu gewähren. (15% Chance, 55 Sek. Abklingzeit) (Procchance: 15%, 55s Abklingzeit)\nVerkaufspreis:" }
entries[116825] = { ["name"] = "Primitive Angelrute", ["text"] = "Wird beim Aufheben gebunden\nUnbekannt\nHaltbarkeit 20 / 20Benötigt eine Horde-Rasse\nAnlegen: +13 Angelfertigkeit.\nBenutzen: Bringt einen Köder an Eurer Angelrute an, der Eure Angelfertigkeit 10 Min. lang um 10 erhöht. (20 Min Abklingzeit)\nBenötigt Nat Pagle\n- Freund\n\"Ist so wild, dass man sie kaum halten kann.\"" }
