entries[116827] = { ["name"] = "Großes Buch der Garnisonsbaupläne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erlernt alle Baupläne für die Garnisonsgebäude der Stufe 1 und 2.\n\"Erstauflage.\"" }
entries[116828] = { ["name"] = "Edelkostümset: \"Der Lichkönig\"", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kleidet Euch wie Arthas der Lichkönig. (10 Sek. Abklingzeit)\n50 Aufladungen\n\"Eine aufwendige Replik, bis hin zu Haarsträhnen. Nutzt sich mit der Zeit ab.\"" }
