entries[117389] = { ["name"] = "Leitstein des Draenorarchäologen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Teleportiert Euch zu einer zufällig gewählten aktiven Grabungsstätte in Draenor. (30 Min Abklingzeit)\nBenötigt Ausgestoßene Arakkoa\n- Ehrfürchtig\n\"Nur in Draenor verwendbar.\"" }
