entries[117391] = { ["name"] = "Perlendster Hellbräuglücksbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Ausdauer\nBenutzen: Eine Schankmaid beschwören, da steppt einfach bei jeder Party der Bär. Winkt ihr zu, um ein Braufestbräu zu bekommen! (3 Min Abklingzeit)" }
