entries[117396] = { ["name"] = "Das Auge von Anzu", ["text"] = "Questgegenstand\nBenutzen: Zerstört ein Nest einer Sethekkwindnatter.\n\"Ein Zauberfokus aus Terokks dunkleren Tagen.\"" }
