entries[117398] = { ["name"] = "Immergrüner Samenbeutel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Zermahlt einen immergrünen Samen, um die zersetzende Verseuchung freizusetzen und Euch in eine Naturgewalt zu verwandeln. (10 Min Abklingzeit)\n3 Aufladungen" }
entries[117401] = { ["name"] = "Nats draenisches Anglertagebuch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Durch das Lesen dieses Buches wird Eure Fertigkeit im Angeln von Draenor permanent um 25 erhöht, bis zu einem Maximum von 100.\nBenötigt Angeln (1)\nBenötigt den Ruf 'Guter Freund' bei Nat Pagle\n\"Seine Notizen sind nicht gerade leicht zu lesen.\"" }
entries[117402] = { ["name"] = "Hochspannungsreflektor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Gegenstand aus dem Ingenieurlabor (1)\nSchmuck\n+ 7 Vielseitigkeit\nBenutzen: Schatten- und Naturzauber werden 5 Sek. lang auf ihren Zaubernden zurückgeworfen. (3 Min Abklingzeit)\n15 Aufladungen\nVerkaufspreis:" }
