entries[117404] = { ["name"] = "Landhai", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Landhai beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Nat Pagle\n- Guter Freund\nBenötigt den Ruf 'Guter Freund' bei Nat Pagle" }
entries[117405] = { ["name"] = "Nats Trinkhut", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nAnlegen: +8 Angelfertigkeit.\nBenutzen: Bringt einen Köder an Eurer Angelrute an, der 10 Min. lang Eure Angelfertigkeit um 10 erhöht. (10 Min Abklingzeit)\nBenötigt Nat Pagle\n- Freund\n\"Sieht mit verschwommener Sicht besser aus.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
